package com.senati.modaapp.data
import android.content.Context
import com.senati.modaapp.data.model.*
class ReporteDao(context:Context){private val h=DBHelper(context);fun resumen():ReporteResumen{val periodo=java.text.SimpleDateFormat("yyyy-MM",java.util.Locale.getDefault()).format(java.util.Date());val atendidos=h.readableDatabase.rawQuery("SELECT COUNT(*),COALESCE(SUM(total),0) FROM pedido WHERE estado='ATENDIDO' AND substr(fecha,1,7)=?",arrayOf(periodo)).use{it.moveToFirst();it.getInt(0) to it.getDouble(1)};val pendientes=h.readableDatabase.rawQuery("SELECT COUNT(*) FROM pedido WHERE estado='PENDIENTE'",null).use{it.moveToFirst();it.getInt(0)};val stock=h.readableDatabase.rawQuery("SELECT modelo,cantidad FROM ropa ORDER BY cantidad DESC,modelo",null).use{c->buildList{while(c.moveToNext())add(StockResumen(c.getString(0),c.getInt(1)))}};return ReporteResumen(atendidos.second,atendidos.first,pendientes,stock)};fun clientes():List<ClienteResumen>{return h.readableDatabase.rawQuery("SELECT c.nombres||' '||c.apellidos,c.telefono,COUNT(p.id) FROM cliente c LEFT JOIN pedido p ON p.id_cliente=c.id GROUP BY c.id ORDER BY COUNT(p.id) DESC,c.nombres",null).use{c->buildList{while(c.moveToNext())add(ClienteResumen(c.getString(0),c.getString(1),c.getInt(2)))}}}}
